//! Minimal terminal size detection used for help-text wrapping.
//!
//! Queries, in order, stdout, stderr and stdin. The first descriptor that is a
//! terminal with a non-zero window size wins.

use std::os::fd::{AsFd, AsRawFd};

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Returns the size of the terminal attached to the standard streams, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(std::io::stdout())
        .or_else(|| terminal_size_of(std::io::stderr()))
        .or_else(|| terminal_size_of(std::io::stdin()))
}

/// Returns the size of the terminal behind the given descriptor, if it is one.
pub fn terminal_size_of<Fd: AsFd>(fd: Fd) -> Option<(Width, Height)> {
    let raw = fd.as_fd().as_raw_fd();
    // SAFETY: `isatty` and `ioctl(TIOCGWINSZ)` only read from the descriptor
    // and write into the provided, correctly sized `winsize` struct.
    unsafe {
        if libc::isatty(raw) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(raw, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) != 0 {
            return None;
        }
        if ws.ws_col > 0 && ws.ws_row > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}
EOF
