/// Help template: a title line with the version followed by the description.
const HELP_TEMPLATE: &str = "\
{name} v{version}
{about}

{usage-heading} {usage}

{all-args}{after-help}";

const FLAGS_SHORT_HELP: &str = "Regex flags. May be combined (like `-f mc`).";

const FLAGS_LONG_HELP: &str = "\
Regex flags. May be combined (like `-f mc`).

c - case-sensitive

e - disable multi-line matching

i - case-insensitive

m - multi-line matching

s - make `.` match newlines

w - match full words only";

const FILES_SHORT_HELP: &str =
    "The path to file(s). This is optional - sd can also read from STDIN";

const FILES_LONG_HELP: &str = "\
The path to file(s). This is optional - sd can also read from STDIN.

Note: sd modifies files in-place by default. See documentation for examples.";

/// Parsed command line options.
#[derive(Debug, Clone)]
pub struct Options {
    /// Display changes instead of applying them.
    pub preview: bool,
    /// Treat `find` and `replace_with` literally.
    pub literal_mode: bool,
    /// Maximum replacements per input (0 = unlimited).
    pub replacements: usize,
    /// Regex flags (`c`, `e`, `i`, `m`, `s`, `w`).
    pub flags: Option<String>,
    /// Pattern to search for.
    pub find: String,
