//! Error type shared by the whole program.

use std::fmt;
use std::io;
use std::path::PathBuf;

/// Result alias using the crate error type.
pub type Result<T> = std::result::Result<T, Error>;

/// All the ways a run can fail.
#[derive(Debug)]
pub enum Error {
    /// A path given on the command line does not exist.
    InvalidPath(PathBuf),
    /// The search pattern failed to compile.
    InvalidRegex(regex::Error),
    /// An I/O error that aborted the run.
    Io(io::Error),
    /// One or more inputs could not be written back.
    FailedProcessing(Vec<(String, Error)>),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidPath(path) => write!(f, "invalid path: {}", path.display()),
            Error::InvalidRegex(err) => write!(f, "invalid regex {err}"),
            Error::Io(err) => write!(f, "{err}"),
            Error::FailedProcessing(failures) => {
                writeln!(f, "Failed processing some inputs")?;
                for (source, err) in failures {
                    writeln!(f, "    {source}: {err}")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for Error {}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        Error::Io(err)
    }
}

impl From<regex::Error> for Error {
    fn from(err: regex::Error) -> Self {
        Error::InvalidRegex(err)
    }
}
EOF
cat > src/unescape.rs <<'EOF'
//! Backslash escape processing for the replacement string (regex mode only).
//!
//! Supported escapes: `\n`, `\r`, `\t`, `\\`, `\'`, `\"`, `\xHH` (two hex
//! digits) and `\uHHHH` (four hex digits). Anything else is left untouched.
//!
//! Note: after a successful `\x`/`\u` escape the character immediately
//! following the hex digits is dropped. This mirrors the reference behaviour.

/// Expands escape sequences in `input`.
pub fn unescape(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut chars = input.chars().peekable();

    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }

        match chars.peek().copied() {
            Some('n') => {
                chars.next();
                out.push('\n');
            }
            Some('r') => {
                chars.next();
                out.push('\r');
            }
            Some('t') => {
                chars.next();
                out.push('\t');
            }
            Some('\\') => {
                chars.next();
                out.push('\\');
            }
            Some('\'') => {
                chars.next();
                out.push('\'');
            }
            Some('"') => {
                chars.next();
                out.push('"');
            }
            Some('x') => {
                let mut lookahead = chars.clone();
                lookahead.next(); // the `x`
                match hex_char(&mut lookahead, 2) {
                    Some(ch) => {
                        out.push(ch);
                        // `x`, two digits and one trailing character.
                        chars.nth(3);
                    }
                    None => out.push('\\'),
                }
            }
            Some('u') => {
                let mut lookahead = chars.clone();
                lookahead.next(); // the `u`
                match hex_char(&mut lookahead, 4) {
                    Some(ch) => {
                        out.push(ch);
                        // `u`, four digits and one trailing character.
                        chars.nth(5);
                    }
                    None => out.push('\\'),
                }
            }
            _ => out.push('\\'),
        }
    }

    out
}

/// Reads exactly `digits` characters and interprets them as a hexadecimal
/// code point.
fn hex_char(chars: &mut impl Iterator<Item = char>, digits: usize) -> Option<char> {
    let text: String = chars.take(digits).collect();
    if text.chars().count() != digits {
        return None;
    }
    let value = u32::from_str_radix(&text, 16).ok()?;
    if digits == 2 && value > u32::from(u8::MAX) {
        return None;
    }
    char::from_u32(value)
}

#[cfg(test)]
mod tests {
    use super::unescape;

    #[test]
    fn simple_escapes() {
        assert_eq!(unescape(r"a\nb"), "a\nb");
        assert_eq!(unescape(r"a\tb"), "a\tb");
        assert_eq!(unescape(r"a\\b"), "a\\b");
        assert_eq!(unescape(r"a\qb"), "a\\qb");
        assert_eq!(unescape("a\\"), "a\\");
    }

    #[test]
    fn hex_escapes_drop_following_char() {
        assert_eq!(unescape(r"\x41"), "A");
        assert_eq!(unescape(r"\x41xy"), "Ay");
        assert_eq!(unescape(r"\u0041xy"), "Ay");
        assert_eq!(unescape(r"\x4G"), "\\x4G");
        assert_eq!(unescape(r"\x+1"), "\u{1}");
        assert_eq!(unescape(r"\uD800x"), "\\uD800x");
    }
}
EOF
echo done"}

