//! A tiny read-only memory map used to read input files.

use std::fs::File;
use std::io;
use std::os::fd::AsRawFd;
use std::ptr;

/// Read-only memory mapping of a whole file.
#[derive(Debug)]
pub struct Mmap {
    ptr: *mut libc::c_void,
    mapped_len: usize,
    len: usize,
}

impl Mmap {
    /// Maps the entire content of `file`.
    ///
    /// Zero-length files are handled by mapping a single (never accessed)
    /// byte, since `mmap` rejects empty mappings.
    pub fn map(file: &File) -> io::Result<Self> {
        let len = usize::try_from(file.metadata()?.len())
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "file too large to map"))?;
        let mapped_len = len.max(1);

        // SAFETY: a fresh private, read-only mapping of a descriptor we own;
        // the pointer is validated against MAP_FAILED before use.
        let ptr = unsafe {
            libc::mmap(
                ptr::null_mut(),
                mapped_len,
                libc::PROT_READ,
                libc::MAP_PRIVATE,
                file.as_raw_fd(),
                0,
            )
        };
        if ptr == libc::MAP_FAILED {
            return Err(io::Error::last_os_error());
        }

        Ok(Mmap {
            ptr,
            mapped_len,
            len,
        })
    }

    /// The mapped bytes.
    pub fn as_slice(&self) -> &[u8] {
        if self.len == 0 {
            return &[];
        }
        // SAFETY: `ptr` points to `mapped_len >= len` readable bytes for as
        // long as `self` lives.
        unsafe { std::slice::from_raw_parts(self.ptr.cast::<u8>(), self.len) }
    }
}

impl Drop for Mmap {
    fn drop(&mut self) {
        // SAFETY: undoing the mapping created in `map`.
        unsafe {
            libc::munmap(self.ptr, self.mapped_len);
        }
    }
}

// The mapping is read-only and owned; sharing it across threads is sound.
unsafe impl Send for Mmap {}
unsafe impl Sync for Mmap {}
