//! Input sources: reading, replacing and writing results back.

use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

use tempfile::NamedTempFile;

use crate::error::{Error, Result};
use crate::mmap::Mmap;
use crate::replacer::Replacer;

/// Where input comes from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Source {
    /// Standard input (result goes to standard output).
    Stdin,
    /// A file that is rewritten in place.
    File(PathBuf),
}

impl Source {
    /// Builds the list of sources from the command line file list.
    pub fn from_paths(paths: Vec<PathBuf>) -> Vec<Source> {
        if paths.is_empty() {
            vec![Source::Stdin]
        } else {
            paths.into_iter().map(Source::File).collect()
        }
    }

    /// Human readable name used in messages.
    pub fn display(&self) -> String {
        match self {
            Source::Stdin => "STDIN".to_owned(),
            Source::File(path) => path.display().to_string(),
        }
    }
}

/// The processed content of a single source.
#[derive(Debug)]
pub struct Processed {
    pub source: Source,
    pub content: Vec<u8>,
}

/// Makes sure every file given exists before anything is touched.
pub fn validate(sources: &[Source]) -> Result<()> {
    for source in sources {
        if let Source::File(path) = source {
            if !path.exists() {
                return Err(Error::InvalidPath(path.clone()));
            }
        }
    }
    Ok(())
}

/// Reads and transforms every source. Stops at the first failure.
pub fn process(sources: Vec<Source>, replacer: &Replacer) -> Result<Vec<Processed>> {
    sources
        .into_iter()
        .map(|source| {
            let content = match &source {
                Source::Stdin => {
                    let mut buffer = Vec::new();
                    io::stdin().lock().read_to_end(&mut buffer)?;
                    replacer.replace(&buffer).into_owned()
                }
                Source::File(path) => {
                    let file = File::open(path)?;
                    let mapped = Mmap::map(&file)?;
                    replacer.replace(mapped.as_slice()).into_owned()
                }
            };
            Ok(Processed { source, content })
        })
        .collect()
}

/// Prints the results to standard output instead of modifying anything.
pub fn preview(results: &[Processed]) -> Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    let show_headers = results.len() > 1;

    for result in results {
        if show_headers {
            if let Source::File(path) = &result.source {
                writeln!(handle, "----- FILE {} -----", path.display())?;
            }
        }
        handle.write_all(&result.content)?;
    }
    handle.flush()?;
    Ok(())
}

/// Writes every result to its destination, collecting per-file failures.
pub fn commit(results: &[Processed]) -> Result<()> {
    let mut failures = Vec::new();

    for result in results {
        let outcome = match &result.source {
            Source::Stdin => write_stdout(&result.content),
            Source::File(path) => write_file(path, &result.content),
        };
        if let Err(err) = outcome {
            failures.push((result.source.display(), err));
        }
    }

    if failures.is_empty() {
        Ok(())
    } else if failures.len() == 1 && results.len() == 1 && results[0].source == Source::Stdin {
        // A lone stdin failure is reported directly.
        Err(failures.remove(0).1)
    } else {
        Err(Error::FailedProcessing(failures))
    }
}

fn write_stdout(content: &[u8]) -> Result<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(content)?;
    handle.flush()?;
    Ok(())
}

/// Atomically replaces `path` with `content`, keeping its permissions.
fn write_file(path: &Path, content: &[u8]) -> Result<()> {
    let target = fs::canonicalize(path)?;
    let parent = target.parent().ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "path has no parent directory")
    })?;
    let metadata = fs::metadata(&target)?;

    let mut temp = NamedTempFile::new_in(parent)?;
    temp.write_all(content)?;
    temp.flush()?;
    temp.as_file().set_permissions(metadata.permissions())?;
    temp.persist(&target).map_err(|err| err.error)?;
    Ok(())
}
