//! `sd` - an intuitive find & replace CLI.

mod cli;
mod error;
mod input;
mod mmap;
mod replacer;
mod unescape;

use error::Result;
use input::Source;
use replacer::Replacer;

fn run(options: cli::Options) -> Result<()> {
    let replacer = Replacer::new(
        &options.find,
        &options.replace_with,
        options.literal_mode,
        options.flags.as_deref(),
        options.replacements,
    )?;

    let sources = Source::from_paths(options.files);
    input::validate(&sources)?;
    let results = input::process(sources, &replacer)?;

    if options.preview {
        input::preview(&results)
    } else {
        input::commit(&results)
    }
}

fn main() {
    let options = cli::parse();
    if let Err(err) = run(options) {
        eprintln!("error: {err}");
        std::process::exit(1);
    }
}
